import {embedded,initialUi,saveUi,transfer as sendCrmTransfer} from './crm-bridge.js';
import {readExchangeFile,exchangePreview,exportExchange,prefilledQuestionnaire} from './wealth-exchange.js';
import {appVersion} from './version.js';
import {documentHtml} from './documents.js';
import {advisorOf,crisisOf,crisisTables,planPeople} from './plan-data.js';
import {planLaunch,crisisEditor,crisisRecordForm,reportSettings,brandHtml} from './plan-ui.js';
import {appearance,inheritanceFamily,issueTarget,figure,familyGroups,familyGroupHtml,assetDescription,familyLabels,relationshipTo,comparisonRows,variantReason,scenarioGuide} from './family-view.js';
import {parseIntake,intakeType,criticalQuestions,choices,budgetLabels} from './intake-contract.js';
import {importQuestionnaire,readyToReview,acceptClientAnswers} from './intake-import.js';
import {presentationHtml} from './presentation.js';
import {calculate,applyDeath,liquidity,clone,validate,age,today} from './engine.js';
import {blank,demo,uid,assetCategories,debtCategories,manualFields,financialFields} from './data.js';
import {CaseRepository,parseCase} from './storage.js';
import {rules} from './rules.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('cs-CZ',{style:'currency',currency:'CZK',maximumFractionDigits:0}).format(x||0);
const pct=x=>new Intl.NumberFormat('cs-CZ',{style:'percent',maximumFractionDigits:2}).format(x);
const repo=new CaseRepository();let cases=[],current=null,page='cases',selected='',scenario='A',beneficiary='',history=[],model=null,lastResult=null,saveStatus='Pouze na tomto zařízení',showAll=false;
let reportType='inheritance',reportRequest=0;
const pages={intake:'Dotazník klienta',cases:'Klientské případy',overview:'Přehled případu',family:'Rodina a vztahy',assets:'Majetek a závazky',simulation:'Dědické scénáře',protection:'Finanční ochrana',manual:'Krizový plán · podklady',report:'Dva klientské výstupy',settings:'Správa případu',method:'Právní metodika'};
const titles={intake:'Co nám klient sdělil.',overview:'Pro rodinu. Pro klid.',family:'Každá rodina má svůj příběh.',assets:'Majetek v souvislostech.',simulation:'Co by se stalo, kdyby…',protection:'Čas a jistota pro pozůstalé.',manual:'Vědět, kam se obrátit.',report:'Vše důležité na jednom místě.',settings:'Aktuální data. Spolehlivější plán.',method:'Pravidla, která můžete dohledat.',cases:'Vaše klientské případy.'};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000);}
function active(){return model||current;}
function personName(id,c=active()){return id==='STATE'?'Česká republika':c?.people.find(p=>p.id===id)?.name||'Neurčeno';}
function opts(list,value){return list.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('');}
function peopleOptions(value='',includeBlank=true,c=current){return opts([...(includeBlank?[['','— vyberte —']]:[]),...c.people.map(p=>[p.id,p.name])],value);}
const input=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const check=(name,label,value)=>`<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}>${label}</label>`;
function metric(label,value,note='',emphasis=false){return `<div class="metric ${emphasis?'emphasis':''}"><div class="label">${label}</div><strong>${value}</strong><small>${note}</small></div>`;}
function totals(c=current){return {assets:c.assets.filter(a=>a.kind==='asset'&&a.currency==='CZK').reduce((s,a)=>s+a.value,0),debts:c.assets.filter(a=>a.kind==='debt'&&a.currency==='CZK').reduce((s,a)=>s+a.value,0)};}
function reset(){history=[];model=null;lastResult=null;}
async function save(invalidate=true){current.updated=new Date().toISOString();if(invalidate)reset();try{await repo.put(current);cases=await repo.all();saveStatus=embedded?'Uloženo u klienta v CRM':'Uloženo na tomto zařízení';}catch(e){saveStatus='Neuloženo — exportujte JSON';toast(e.message);}render();}
function defaultPartner(c,id){const r=c.relations.find(r=>(r.a===id||r.b===id)&&(!r.end||r.end>c.date)&&r.start<=c.date);const p=c.people.find(p=>p.id===(r?.a===id?r?.b:r?.a));return p&&!p.dead&&!p.death?p.id:'';}
function openCase(id){current=cases.find(c=>c.id===id);selected=current.people.find(p=>!p.dead&&!p.death)?.id||'';beneficiary=defaultPartner(current,selected);scenario='A';page='overview';reset();render();}
function notice(errors){return `<div class="notice error"><strong>Doplňte jen tyto konkrétní údaje</strong><ul>${errors.map(x=>{const t=issueTarget(active(),x,selected);return `<li><button class="issue-link" ${t.assetId?`data-edit-asset="${esc(t.assetId)}" data-focus-field="${t.field}"`:t.personId?`data-edit-person="${esc(t.personId)}" data-focus-field="${t.field}"`:t.page?`data-page="${t.page}"`:`data-jump-field="${t.field}"`}>${esc(x)} → Otevřít a upravit</button></li>`;}).join('')}</ul></div>`;}

function render(){
 if(embedded&&current){saveUi({page,selected,scenario,beneficiary,model,history,reportType});if(window.CrmFamilyFrame&&!saveStatus.startsWith('Neuloženo'))window.CrmFamilyFrame.dirty=false;}
 const caseNav=Object.entries(pages).filter(([key])=>key!=='cases'&&(current||key==='method'));
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div>${brandHtml()}</div></div><div class="nav"><button data-page="cases" class="${page==='cases'?'active':''}"><span class="num">▦</span>Klientské případy</button></div><div class="nav-label">${current?'Pracovní prostor':'Nástroje'}</div><nav class="nav" aria-label="Hlavní navigace">${caseNav.map(([key,label],i)=>`<button data-page="${key}" class="${page===key?'active':''}"><span class="num">${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</nav><div class="sidebar-foot">◈ &nbsp; Soukromí na prvním místě<br>Plán se ukládá u klienta v CRM.<br><br>Odborná právní revize čeká.<br><br>Fair Life · Filip Solár<br><strong class="app-version">Verze ${appVersion}</strong></div></aside><main class="main"><header class="topbar"><div class="crumb">Pracovní prostor &nbsp; / &nbsp; <b>${esc(current?.name||'Klientské případy')}</b></div><div class="toolbar"><span class="saved">${saveStatus}</span>${current?'<button class="small" data-action="prefill-questionnaire">↓ Dotazník pro klienta</button><button class="small" data-action="exchange-export">↓ Přenos do CRM</button><button class="small" data-action="export">↓ Záloha JSON</button>':''}</div></header><div class="content"><div class="heading"><div><div class="eyebrow">${pages[page]} ${current?.demo?' · UKÁZKOVÁ DATA':''}</div><h1>${titles[page]}</h1><p class="sub">${page==='cases'?'Přehled rodin, jejich plánů a dalších kroků.':page==='simulation'?'Prozkoumejte dědické podíly v kontextu skutečných rodinných vazeb.':'Rodinný krizový a dědický plán · pracovní finanční model'}</p></div><div class="toolbar">${current&&page!=='cases'?'<button data-page="report">↗ Oba plány</button>':''}${page==='cases'?'<button class="primary" data-action="new">+ Nový případ</button>':''}</div></div>${renderPage()}<div class="footnote">Plán je součástí klientských dat a záloh CRM. Výpočty jsou orientační; před klientským použitím je musí zkontrolovat český právník nebo notář.</div></div></main></div>`;
}
function renderPage(){if(current?.intake&&!current.intake.reviewed&&page==='overview')return intakePage();switch(page){case 'intake':return intakePage();case 'cases':return dashboard();case 'overview':return overview();case 'family':return family();case 'assets':return assets();case 'simulation':return simulation();case 'protection':return protection();case 'manual':return manual();case 'report':return reportPage();case 'settings':return settings();case 'method':return methodology();}}
function dashboard(){return `${questionnaireTools()}<div class="toolbar" style="margin-bottom:20px"><button data-action="import">↑ Importovat JSON</button><button data-action="demo">Otevřít ukázkovou rodinu</button></div><div class="case-grid">${cases.map(c=>`<article class="case-card"><span class="badge ${c.demo?'gold':''}">${c.demo?'Smyšlená ukázka':'Klientský případ'}</span><h2>${esc(c.name)}</h2><p>${c.people.length} osob · ${c.assets.length} majetkových položek<br>Aktualizace ${new Date(c.updated).toLocaleDateString('cs-CZ')}</p><div class="toolbar"><button class="primary" data-open="${esc(c.id)}">Otevřít případ →</button><button class="small danger" data-delete-case="${esc(c.id)}" aria-label="Smazat případ ${esc(c.name)}">Smazat</button></div></article>`).join('')||'<div class="empty">Začněte novým případem nebo otevřete ukázkovou rodinu.</div>'}</div><div class="notice">Data se ukládají pouze do tohoto prohlížeče. Smazání dat webu odstraní uložené případy. Synchronizace mezi zařízeními není zapnutá.</div>`;}
function overview(){const t=totals(),l=liquidity(current.financial);return `${planLaunch(current)}<div class="metrics">${metric('Majetek domácnosti',money(t.assets),'Součet zadaných položek v CZK')}${metric('Závazky domácnosti',money(t.debts),'Nejde o rozdělení odpovědnosti')}${metric('Čistá majetková hodnota',money(t.assets-t.debts),'Před vypořádáním dědictví',true)}${metric('Chybějící finanční rezerva',(current.intake?.unknownFinancial?.length||current.financial.months<1)?'Údaje k doplnění':money(l.gap),`${current.financial.months} měsíců zajištění`)}</div><section class="panel"><h2>Váš majetek podle zadaných údajů</h2>${assetOverview(current)}</section><div class="columns"><section class="panel"><div class="panel-head"><h2>Vaše rodina v souvislostech</h2><button class="small" data-page="family">Upravit rodinu</button></div>${tree(inheritanceFamily(current,selected,{scenario,beneficiary}),null,current)}</section><section class="panel"><div class="eyebrow">Další krok</div><h2>Projděte s klientem možné situace.</h2><p>Vyberte osobu ve stromu a podívejte se, co by její úmrtí znamenalo pro rodinu a majetek.</p><button class="primary" data-page="simulation">Prozkoumat dědický scénář →</button><div class="tip">${current.complete?'Okruh rodiny byl označen jako úplný.':'Nejdříve doplňte rodinné vztahy a potvrďte úplnost vstupů ve správě případu.'}<br>Současný výběr: <b>${esc(personName(selected))}</b></div><div class="manual-step"><b>01</b><span>Rodina a právní vztahy<br><small>${current.people.length} osob v evidenci</small></span></div><div class="manual-step"><b>02</b><span>Majetek a vlastnictví<br><small>${current.assets.length} položek k posouzení</small></span></div><div class="manual-step"><b>03</b><span>Krizový manuál<br><small>${Object.values(current.manual).filter(Boolean).length} vyplněných oblastí</small></span></div></section></div>`;}
function tree(c,result,fullCase=c){return `<div class="kin-map">${familyGroups(c).map(g=>familyGroupHtml(fullCase,g,{interactive:true,selected,deceased:result?.deceased})).join('')}</div><p class="footnote">Šipka propojuje rodiče s jejich dětmi. Zobrazujeme osoby pro tento plán; úplná evidence je v části Rodina a vztahy.</p>`;}

function personDetail(){const p=current.people.find(p=>p.id===selected);if(!p)return '';const owned=current.assets.filter(a=>a.owners[p.id]>0);return `<div class="panel"><div class="panel-head"><div><div class="eyebrow">Vybraná osoba</div><h2>${esc(p.name)}</h2></div><div class="toolbar"><button data-edit-person="${esc(p.id)}">Detail osoby</button><button class="primary" data-action="simulate-person" ${p.dead||p.death?'disabled':''}>Simulovat úmrtí této osoby</button></div></div><p>${familyLabels(current,p).map(esc).join('<br>')}</p><p>${owned.length?owned.map(a=>esc(a.name)+' · '+pct(a.owners[p.id])+' modelového podílu').join('<br>'):'Bez přiřazených majetkových položek.'}</p></div>`;}
function family(){return `<div class="panel"><div class="panel-head"><h2>Rodinný strom</h2><div class="toolbar"><button data-action="person">+ Osoba</button><button data-action="children">+ Více dětí</button><button data-action="relation">+ Partnerský vztah</button></div></div>${tree(current)}<p class="footnote">Kliknutím vyberete osobu. Rodičovské vazby upravíte v detailu osoby; sourozenci a další generace se odvodí automaticky.</p></div>${personDetail()}<div class="panel"><div class="panel-head"><h2>Osoby a právní vztahy</h2></div><div class="table-wrap"><table><thead><tr><th>Osoba</th><th>Rodiče</th><th>Stav / dokumenty</th><th></th></tr></thead><tbody>${current.people.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.birth||'Datum narození neuvedeno')}</small></td><td>${p.parents.map(id=>esc(personName(id))).join(', ')||'—'}</td><td>${p.dead||p.death?'Zemřelá':'Žijící'}${p.documents?'<small>Pořízení pro případ smrti</small>':''}${p.adopted?'<small>Osvojení · posoudit</small>':''}</td><td><button class="small" data-edit-person="${esc(p.id)}">Upravit</button></td></tr>`).join('')}</tbody></table></div></div><div class="two"><section class="panel"><div class="panel-head"><h2>Manželství a partnerství</h2><button class="small" data-action="relation">+ Vztah</button></div>${current.relations.map(r=>`<div class="result-row"><div><strong>${esc(personName(r.a))} & ${esc(personName(r.b))}</strong><small>${esc(({marriage:'Manželství',partner:'Nesezdané soužití',registered:'Registrované partnerství',partnership:'Partnerství'})[r.type])} · ${esc(r.start)} — ${esc(r.end||'trvá')}</small></div><button class="small" data-edit-relation="${r.id}">Upravit</button></div>`).join('')||'<p>Zatím bez vztahů.</p>'}</section><section class="panel"><div class="panel-head"><h2>Společná domácnost</h2><button class="small" data-action="household">+ Domácnost</button></div><p>Samotné partnerství nezakládá automatický dědický nárok.</p>${current.households.map(h=>`<div class="result-row"><div><strong>${esc(personName(h.a))} & ${esc(personName(h.b))}</strong><small>Od ${esc(h.since)} · ${h.verified?'Podmínky ověřeny':'Neověřeno'}</small></div><button class="small danger" data-delete-household="${h.id}">Odebrat</button></div>`).join('')}</section></div>`;}
function assets(){const t=totals();return `<div class="metrics">${metric('Majetek',money(t.assets),'Pouze CZK')}${metric('Závazky',money(t.debts),'Pouze CZK')}${metric('Čistá hodnota',money(t.assets-t.debts),'Celá evidovaná domácnost',true)}${metric('Položky k ověření',current.assets.filter(a=>!a.verified||['unknown','modified'].includes(a.regime)).length,'Nejasnosti blokují výpočet')}</div><div class="panel"><div class="panel-head"><h2>Majetek a závazky</h2><div class="toolbar"><button data-add-asset="debt">+ Závazek</button><button class="primary" data-add-asset="asset">+ Majetek</button></div></div><div class="table-wrap"><table><thead><tr><th>Položka</th><th>Vlastníci / modelové podíly</th><th>Režim</th><th class="number">Hodnota</th><th></th></tr></thead><tbody>${current.assets.map(a=>`<tr><td><b>${esc(a.name)}</b><small>${esc(a.category)} · ${esc(a.acquisition||'Nabytí neuvedeno')} · ${a.liquid?'Likvidní':'Nelikvidní'}${a.kind==='debt'?' · ZÁVAZEK':''}</small></td><td>${Object.entries(a.owners).map(([id,n])=>`${esc(personName(id))} ${pct(n)}`).join('<br>')}</td><td><span class="badge ${a.verified?'':'gold'}">${esc(regimeName(a.regime))}</span><small>${a.clientProvided?'Údaj klienta':a.verified?'Vstup potvrzen':'Vyžaduje doplnění'}</small></td><td class="number">${a.kind==='debt'?'− ':''}${a.currency==='CZK'?money(a.value):esc(a.value+' '+a.currency)}</td><td><button class="small" data-edit-asset="${esc(a.id)}">Upravit</button></td></tr>`).join('')||'<tr><td colspan="5">Zatím bez položek.</td></tr>'}</tbody></table></div><div class="notice">Zápis jediného vlastníka v katastru sám o sobě nepotvrzuje výlučné vlastnictví. U SJM je 50/50 pouze výslovně zvolený finanční model vypořádání; vnosy a smluvené režimy posoudí notář.</div></div>`;}
const regimeName=x=>({exclusive:'Výlučné',shares:'Podílové',sjm:'Standardní SJM',modified:'Upravené / smluvené',unknown:'Nejasné'})[x];
const scenarioNames={A:'Současný stav',B:'Bez závěti',C:'Existující závěť',D:'Zabezpečení partnera',E:'Zabezpečení dětí',F:'Převody za života',G:'Následná úmrtí'};
function getResult(){if(!selected)return null;return calculate(active(),selected,{scenario:scenario==='G'?'A':scenario,beneficiary});}
function simulation(){const c=active();lastResult=scenario==='F'?null:getResult();const r=lastResult;return `<div class="scenario-tabs">${Object.entries(scenarioNames).map(([id,name])=>`<button data-scenario="${id}" class="${scenario===id?'active':''}">${id} · ${name}</button>`).join('')}</div><div class="panel"><div class="simulation-controls"><label>Osoba pro simulaci úmrtí<select id="sim-person">${peopleOptions(selected,true,c)}</select></label><label>Datum modelové události<input type="date" id="sim-date" value="${c.date}" ${history.length?'min="'+history.at(-1).date+'"':''}></label>${scenario==='D'?`<label>Zabezpečený partner<select id="beneficiary">${peopleOptions(beneficiary,true,c)}</select></label>`:''}<button data-action="reset">↶ Vrátit simulaci</button></div>${history.length?`<div class="history">Posloupnost: ${history.map((h,i)=>`${i+1}. ${esc(h.name)} (${h.date})`).join(' → ')}</div>`:''}</div>${c.international?'<div class="notice">Zahraniční vazba: počítáme orientačně podle českého práva. Přeshraniční dopady vyžadují individuální právní posouzení; tato poznámka výpočet neblokuje.</div>':''}${scenario==='F'?transferPanel():r?.errors?.length?notice(r.errors):r?`<div class="metrics">${metric('Aktiva v pozůstalosti',money(r.gross),'Po modelovém vypořádání vlastnictví')}${metric('Dluhy v modelu',money(r.debt),'Bez určení odpovědnosti věřitelům')}${metric('Čistá pozůstalost',money(r.net),'Orientační základ pro rozdělení',true)}${metric('Zákonná posloupnost',r.class?r.class+'. třída':'Odúmrť',r.class?'§ '+(1634+r.class)+' občanského zákoníku':'§ 1634 občanského zákoníku')}</div>`:'<div class="notice">Vyberte osobu pro simulaci.</div>'}<div class="columns simulation-columns ${showAll?'expanded-family':''}"><section class="panel"><div class="panel-head"><h2>Rodina a dědické vazby</h2><button class="small" data-action="toggle-tree">${showAll?'Zobrazit relevantní osoby':'Rozšířit na celou rodinu'}</button></div>${treeForSimulation(c,r)}<p class="footnote">Šedá postavička označuje modelové úmrtí.</p></section><section class="panel"><div class="panel-head"><h2>${r?.allocation?'Porovnání hodnotových variant':'Orientační rozdělení'}</h2><span class="badge">${esc(scenarioNames[scenario])}</span></div>${r&&!r.errors.length?resultSummary(r):'<p>Pro výpočet doplňte označený údaj. Kliknutím na upozornění ho rovnou otevřete.</p>'}${scenario==='G'&&r&&!r.errors.length?'<div class="tip">Přenesením se v pracovní kopii rozdělí modelové podíly každé položky. Poté vyberte další osobu a datum úmrtí.</div><button class="primary" data-action="apply-death">Přenést výsledek do další události →</button>':''}</section></div>${r&&!r.errors.length?`<section class="panel"><h2>Z čeho se dědictví počítá</h2>${assetBasis(c,r)}</section><div class="panel"><h2>${r.allocation?'Podrobný výsledek zvolené varianty':'Podrobná tabulka zákonného modelu'}</h2>${resultTable(r)}<div class="notice">${r.warnings.map(esc).join('<br>')}</div></div>`:''}<section class="panel scenario-help"><h2>Jak to číst a co lze připravit</h2><p>${esc(scenarioGuide[scenario])}</p><p><a href="https://portal.gov.cz/informace/nepominutelny-dedic-INF-78" target="_blank" rel="noopener">Povinné díly – gov.cz</a> · <a href="https://www.nkcr.cz/vasi-notari/detail/239_1104-faq-casto-kladene-dotazy-(zavet-a-dedeni)" target="_blank" rel="noopener">Závěť a manželé – Notářská komora</a></p></section>${scenario==='C'?`<div class="panel"><h2>Existující pořízení pro případ smrti</h2><p>${esc(c.people.find(p=>p.id===selected)?.documentNotes||'V detailu osoby doplňte umístění dokumentu, datum a zamýšlený účinek. Platnost a konkrétní rozdělení musí posoudit notář.')}</p><button data-edit-person="${esc(selected)}">Upravit dokumenty osoby</button></div>`:''}`;}

function treeForSimulation(c,r){return tree(showAll?c:inheritanceFamily(c,selected,{scenario,beneficiary}),r?.errors?.length?null:r,c);}

function resultSummary(r){if(r.allocation)return `<div class="notice">Hypotetická závětní varianta k projednání s notářem. Sloupec „Varianta“ ukazuje změněné dědictví; vlastní majetek zůstává zvlášť.</div><div class="table-wrap"><table><thead><tr><th>Osoba / důvod</th><th>Ze zákona</th><th>Varianta</th></tr></thead><tbody>${comparisonRows(active(),r).map(a=>`<tr class="${a.priority?'priority-row':''}"><td><b>${esc(personName(a.id))}</b><small>${esc(relationshipTo(active(),a.id,r.deceased))}</small><small>${esc(variantReason(a,r))}</small>${r.scenario==='D'&&a.descendant?`<small>${money(a.law)} × ${a.age<18?'¾':'¼'} = ${money(a.value)}</small>`:''}</td><td>${money(a.law)}</td><td><b>${money(a.value)}</b></td></tr>`).join('')}</tbody></table></div>`;return `<div class="result-list">${r.heirs.map(h=>`<div class="result-row"><div><strong>${esc(personName(h.id))}</strong><small>${esc(relationshipTo(active(),h.id,r.deceased))} · ${pct(h.share)}</small></div><div class="value">${money(h.amount)}<small>Hodnota podílu</small></div></div>`).join('')}</div><div class="tip">Dědický podíl není požadavek na okamžité vyplacení v hotovosti. Potřebu peněz plánujte samostatně.</div>`;}
function assetBasis(c,r){return `<div class="table-wrap"><table><thead><tr><th>Majetek / dluh</th><th>Komu patří a jak vznikl</th><th>Celá položka</th><th>Podíl ve scénáři</th><th>Do pozůstalosti</th></tr></thead><tbody>${c.assets.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td>${esc(assetDescription(c,a))}</td><td>${money(a.value)}</td><td>${pct(a.owners[r.deceased]||0)}</td><td>${a.kind==='debt'?'− ':''}${money(a.value*(a.owners[r.deceased]||0))}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Nula znamená, že tato položka podle zadaného vlastnictví patří jiné osobě. Dar označuje způsob nabytí; není to další částka navíc.</p>`;}
function resultTable(r){return `<div class="table-wrap"><table><thead><tr><th>Osoba / vztah</th><th>Ze zákona</th>${r.allocation?'<th>Dědictví ve variantě</th>':''}<th>Povinný díl</th><th>Vlastní majetek po vypořádání</th><th>Celkem ${r.allocation?'ve variantě':'ze zákona'}</th></tr></thead><tbody>${comparisonRows(active(),r).map(a=>`<tr class="${a.priority?'priority-row':''}"><td><b>${esc(personName(a.id))}</b><small>${esc(relationshipTo(active(),a.id,r.deceased))}</small></td><td>${money(a.law)}</td>${r.allocation?`<td><b>${money(a.value)}</b></td>`:''}<td>${a.minimum?money(a.minimum)+`<small>${a.age<18?'¾':'¼'} zákonného podílu</small>`:'—'}</td><td>${money(a.own)}</td><td><b>${money(a.total)}</b></td></tr>`).join('')}</tbody></table></div><p class="footnote">Vlastní majetek zahrnuje modelové vypořádání SJM a přiřazené závazky. Celkem = vlastní čistý majetek + dědictví ${r.allocation?'ve zvolené variantě':'ze zákona'}. Povinný díl není další částka navíc. Model neurčuje konkrétní věci, splatnost ani odpovědnost vůči věřitelům.</p>`;}

function transferPanel(){return `<div class="panel"><h2>Model převodu majetku za života</h2><p>Vytvoří samostatnou kopii případu, ve které převedete modelový podíl jedné položky. Původní případ zůstane zachován.</p><div class="notice">Darování může být nevratné a ovlivnit započtení na dědické či povinné díly. Model převodu nepotvrzuje platnost ani daňové důsledky. Navazující právní výpočet bude vyžadovat individuální posouzení.</div><button class="primary" data-action="transfer">Vytvořit variantu převodu</button></div>`;}
function protection(){const f=current.financial,l=liquidity(f);return `${current.intake&&(!current.intake.reviewed||current.intake.unknownFinancial?.length||current.financial.months<1)?'<div class="notice">Odpovědi ještě čekají na kontrolu. Neznámé částky doplňte; zástupné nuly nejsou potvrzený výsledek.</div>':''}<div class="metrics" ${current.intake&&(!current.intake.reviewed||current.intake.unknownFinancial?.length||current.financial.months<1)?'hidden':''}>${metric('Měsíční deficit',money(l.deficit),'Výdaje minus příjem pozůstalých')}${metric('Celková potřeba',money(l.need),`${f.months} měsíců + jednorázové částky`)}${metric('Dostupné krytí',money(f.reserve+f.insurance),'Rezerva + očekávané pojistné plnění')}${metric('Zbývá zajistit',money(l.gap),'Orientační potřeba likvidity',true)}</div><div class="two"><form id="financial-form" class="panel"><h2>Finanční plán pozůstalých</h2><div class="form-grid">${Object.entries(financialFields).map(([key,label])=>input(key,label+(key==='months'?'':' (Kč)'),current.intake?.unknownFinancial?.includes(key)?'':f[key],'number',`min="${key==='months'?1:0}" step="1" required`)).join('')}</div><button class="primary" style="margin-top:20px">Přepočítat a uložit</button></form><section class="panel"><div class="eyebrow">Prostor pro rozhodnutí</div><h2>Nejdřív potřeba. Potom řešení.</h2><p>Rezervu, pravidelný příjem a pojištění lze kombinovat. Model nedoporučuje konkrétní produkt a nepředpokládá automatické pojistné plnění.</p><div class="progress" ${current.intake&&(!current.intake.reviewed||current.intake.unknownFinancial?.length||current.financial.months<1)?'hidden':''}><i style="width:${l.need?Math.min(100,l.covered/l.need*100):100}%"></i></div><p class="footnote" ${current.intake&&(!current.intake.reviewed||current.intake.unknownFinancial?.length||current.financial.months<1)?'hidden':''}>Pokryto ${l.need?pct(l.covered/l.need):'100 %'} modelované potřeby</p><div class="notice">Zadejte jen rezervu skutečně dostupnou pozůstalým. Nezapočítejte ji zároveň jako další příjem. Dědické podíly se automaticky nepřičítají k hotovostnímu vypořádání.</div><p>Pojistné plnění závisí na smlouvě, obmyšlených osobách, výlukách a šetření pojišťovny. Kontakty a čísla smluv uložte do krizového manuálu.</p><button data-page="manual">Doplnit krizový manuál →</button></section></div>`;}
function manual(){return `${crisisEditor(current)}<div class="notice">Ukládejte umístění dokumentů a kontakty. Nevkládejte hesla, PINy, přístupové kódy ani soukromé klíče.</div><form id="manual-form" class="panel"><div class="panel-head"><h2>Praktické informace pro domácnost</h2><button class="primary">Uložit manuál</button></div><div class="form-grid">${Object.entries(manualFields).map(([key,label])=>`<label>${label}<textarea name="${key}" placeholder="Doplňte konkrétní osoby, kontakty a kroky…">${esc(current.manual[key])}</textarea></label>`).join('')}</div></form><div class="panel"><h2>První kroky k přípravě</h2><div class="manual-step"><b>01</b><span>Domluvte osobu, která pomůže rodině s každodenním provozem a péčí o děti.</span></div><div class="manual-step"><b>02</b><span>Sepište umístění dokumentů a kontakty na poradce, zaměstnavatele a pojišťovny.</span></div><div class="manual-step"><b>03</b><span>S notářem proberte právní dokumenty, správu pozůstalosti, dluhy a ochranu nezletilých.</span></div></div>`;}
function reportPage(){setTimeout(()=>fillPresentation(),0);return `${planLaunch(current)}${reportSettings(current)}<div class="report-tabs" role="group" aria-label="Typ výstupu">${[['inheritance','Dědický plán'],['crisis','Krizový plán'],['short','Krátká prezentace']].map(([k,l])=>`<button data-report-type="${k}" class="${reportType===k?'primary':''}">${l}</button>`).join('')}</div><div class="toolbar"><button class="primary" data-action="print">Tisk / uložit jako PDF</button><button data-action="html">↓ Stáhnout samostatné HTML</button><button data-action="both-html">↓ Stáhnout oba plány</button></div><p>${reportType==='short'?'Krátká prezentace: A4 na šířku.':'Dokument: A4 na výšku.'} Tisk při měřítku 100 %, bez záhlaví a zápatí prohlížeče. HTML funguje i bez internetu.</p><iframe id="presentation-frame" title="${reportType==='crisis'?'Krizový plán':reportType==='short'?'Krátká prezentace':'Dědický plán'}" style="width:100%;height:85vh;border:1px solid #d7e4ee;border-radius:14px"></iframe>`;}
let presentationAssets;
async function getPresentation(kind=reportType){presentationAssets??=Promise.all(['./src/presentation.css','./src/style.css','./Fustat-OFL.txt','./src/documents.css'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error('Nelze načíst vzhled výstupu.');return r.text();})));const [css,style,license,docCss]=await presentationAssets;const font=(style.match(/@font-face\s*\{[^}]+\}/g)||[]).join('\n')+'/*'+license+'*/';return kind==='short'?presentationHtml(active(),{selected,scenario,beneficiary,history},css,font):documentHtml(current,kind,docCss,font);}
async function fillPresentation(){const request=++reportRequest;try{const html=await getPresentation(),f=$('#presentation-frame');if(f&&request===reportRequest)f.srcdoc=html;}catch(e){toast(e.message);}}
function editCrisis(key,index){if(!crisisTables[key])return;const row=crisisOf(current)[key][index]||{};modal('Upravit '+crisisTables[key].single,crisisRecordForm(key,row),async f=>{const c=clone(current);c.crisis=crisisOf(c);const updated={id:row.id||uid(),...Object.fromEntries(f)};if(!Object.values(updated).some((v,i)=>i>0&&v.trim()))throw Error('Vyplňte alespoň jeden údaj.');if(index===undefined)c.crisis[key].push(updated);else c.crisis[key][index]=updated;await commitCandidate(c);},{deleteFn:index!==undefined?async()=>{current.crisis=crisisOf(current);current.crisis[key].splice(index,1);await save(false);}:undefined});}
function questionnaireTools(){return `<section class="panel"><h2>Dotazník pro klienta</h2><p>Pošlete klientovi odkaz nebo samostatný HTML soubor. Na konci stáhne odpovědi a předá vám soubor JSON. Zde ho nahrajete jako nový případ. Odpovědi se automaticky nikam neposílají.</p><div class="toolbar"><a class="button" href="./dotaznik.html" target="_blank" rel="noopener">Otevřít dotazník ↗</a><button data-action="questionnaire-link">Kopírovat odkaz</button><button data-action="questionnaire-html">↓ Dotazník HTML</button><button class="primary" data-action="import">↑ Nahrát odpovědi / zálohu</button></div></section>`;}
function intakePage(){const q=current?.intake;return questionnaireTools()+(!q?'<section class="panel">Tento případ nevznikl z dotazníku.</section>':`<section class="panel"><h2>${q.reviewed?'Podklady převzaty':'Jak chcete s odpověďmi pokračovat?'}</h2>${q.source.status==='draft'?'<div class="notice">Pracovní podklady, nikoli klientem dokončený dotazník. Pro klienta stáhněte předvyplněný dotazník nahoře. Neznámé údaje a nepotvrzená úplnost zůstávají k doplnění.</div>':''}<p>Údaje použijeme tak, jak byly předány. Nemusíte znovu potvrzovat každou částku ani psát kontrolní poznámky. Neznámé odpovědi zůstanou označené.</p><div class="toolbar"><button class="primary" data-accept-intake> Přebrat podklady a otevřít přehled</button><button data-page="assets">Nejdřív chci údaje upravit</button></div></section><section class="panel"><h2>Tohle nám klient uvedl</h2>${assetOverview(current)}${tree(current)}</section>${q.issues.length?`<details class="panel"><summary>Otázky k případnému doplnění (${q.issues.length})</summary><ul>${q.issues.map(i=>`<li>${esc(i.label)}</li>`).join('')}</ul><p>Nejde o povinný kontrolní seznam. Údaje můžete kdykoli upravit v rodině, majetku nebo finanční ochraně.</p></details>`:''}`);}
function assetOverview(c){return `<div class="asset-summary">${c.assets.map(a=>`<article><span class="asset-picture" aria-hidden="true">${a.kind==='debt'?'−':a.category==='Nemovitosti'?'⌂':'▣'}</span><div><h3>${esc(a.name)}</h3><b>${a.intakeUnknownValue?'Hodnotu doplníme':a.currency==='CZK'?money(a.value):esc(a.value+' '+a.currency)}</b><p>${esc(assetDescription(c,a))}</p></div></article>`).join('')||'<p>Klient neuvedl majetkové položky.</p>'}</div>`;}

function settings(){return `<form id="settings-form" class="panel"><h2>Základní nastavení a ověření vstupů</h2><div class="form-grid">${input('name','Název případu',current.name,'text','required')}${input('date','Datum modelu',current.date,'date','required')}</div><div class="checks">${check('complete','Potvrzuji, že byly doplněny všechny relevantní osoby, vztahy a majetkové položky; neuvedené osoby nezakládají další dědický nárok.',current.complete)}${check('sjmConfirmed','Pro finanční model potvrzuji zjednodušené vypořádání standardního SJM v poměru 50/50, bez vnosů a sporů.',current.sjmConfirmed)}${check('international','Existuje zahraniční prvek / nejistota rozhodného práva.',current.international)}${check('gifts','Existují dary nebo převody vyžadující posouzení započtení.',current.gifts)}</div><button class="primary">Uložit nastavení</button></form><section class="panel"><h2>Data a aktualizace</h2><p>Poslední změna: ${new Date(current.updated).toLocaleString('cs-CZ')}. Data nejsou synchronizována a nejsou v prohlížeči šifrována. Zařízení chraňte přístupovým heslem a zálohy uchovávejte bezpečně.</p><div class="toolbar"><button data-action="export">Exportovat JSON</button><button data-action="import">Importovat jako nový případ</button><button data-action="duplicate">Vytvořit kopii případu</button></div></section>`;}
function methodology(){return `<div class="notice">Stav všech pravidel: čekají na odbornou revizi českým právníkem nebo notářem. Automatický výpočet je omezen na podmínky uvedené v metodice; vyplnění formuláře není právní ověření.</div><div class="toolbar" style="margin-bottom:20px"><a href="./docs/METODIKA.md" target="_blank" rel="noopener">Úplná metodika v1 ↗</a><a href="https://e-sbirka.gov.cz/sb/2012/89" target="_blank" rel="noopener">Občanský zákoník v e-Sbírce ↗</a></div><div class="method-grid">${rules.map(r=>`<article><span class="badge gray">${r.id} · ${r.section}</span><h3 style="margin-top:12px">${r.name}</h3><p>${r.method}</p><p>${r.conditions}<br>${r.exceptions}</p><p><b>Příklad:</b> ${r.test}</p><p>Kontrola zdrojů ${r.checked}<br>${r.expertStatus}</p><a href="${r.source}" target="_blank" rel="noopener">Znění ustanovení ↗</a></article>`).join('')}</div>`;}
function modal(title,body,onSubmit,{deleteFn,submitLabel}={}){const d=$('#dialog');d.innerHTML=`<form id="dialog-form"><h2>${title}</h2>${body}<div class="actions">${deleteFn?'<button type="button" class="danger" id="delete-item">Smazat</button>':''}<button type="button" id="close-dialog">Zrušit</button><button class="primary">${esc(submitLabel||(title.startsWith('Smazat')?'Smazat případ':'Uložit'))}</button></div><div id="form-error" role="alert"></div></form>`;d.showModal();$('#close-dialog').onclick=()=>d.close();if(deleteFn)$('#delete-item').onclick=async()=>{try{await deleteFn();d.close();}catch(e){$('#form-error').textContent=e.message;}};$('#dialog-form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(new FormData(e.target));d.close();}catch(e){$('#form-error').textContent=e.message;}};}
function commitCandidate(candidate){const errors=validate(candidate);if(errors.length)throw Error(errors.join(' '));const invalidate=['date','people','assets','relations','households','complete','sjmConfirmed','international','gifts'].some(k=>JSON.stringify(current[k])!==JSON.stringify(candidate[k]));Object.assign(current,candidate);return save(invalidate);}
function editPerson(id){const p=current.people.find(p=>p.id===id)||{id:uid(),name:'',birth:'',parents:[]};modal(id?'Detail osoby':'Nová osoba',`<div class="form-grid">${input('name','Jméno a příjmení',p.name,'text','required maxlength="120"')}<label>Postavička<select name="appearance">${opts([['neutral','Neutrální'],['male','Muž'],['female','Žena']],appearance(current,p))}</select></label>${input('birth','Datum narození',p.birth,'date')}${input('death','Datum úmrtí (pokud je známé)',p.death,'date')}<label>Právní rodič 1<select name="parent1">${peopleOptions(p.parents[0])}</select></label><label>Právní rodič 2<select name="parent2">${peopleOptions(p.parents[1])}</select></label></div><div class="checks">${check('dead','Osoba zemřela (i pokud neznáme datum).',p.dead||p.death)}${check('adopted','Osvojení — právní účinky vyžadují posouzení.',p.adopted)}${check('exception','Vydědění, odmítnutí, zřeknutí, nezpůsobilost nebo jiná právní výjimka.',p.exception)}${check('documents','Existuje závěť, dědická smlouva nebo odkaz.',p.documents)}</div>${p.id===(current.exchangeClientId||(current.intake?'self':planPeople(current)[0]?.id))?'<div class="form-grid">'+input('clientEmail','E-mail klienta',current.contact?.email||'','email')+input('clientPhone','Telefon klienta',current.contact?.phone||'','tel')+input('clientAddress','Adresa klienta',current.contact?.address||'')+'</div>':''}<label>Dokumenty, umístění a zamýšlené účinky<textarea name="documentNotes">${esc(p.documentNotes)}</textarea></label><label>Poznámka<textarea name="notes">${esc(p.notes)}</textarea></label>`,async f=>{const candidate=clone(current);if(f.has('clientEmail'))candidate.contact={email:f.get('clientEmail'),phone:f.get('clientPhone'),address:f.get('clientAddress')};const updated={...p,appearance:f.get('appearance'),name:f.get('name').trim(),birth:f.get('birth'),death:f.get('death'),dead:f.has('dead')||!!f.get('death'),parents:[f.get('parent1'),f.get('parent2')].filter(Boolean),adopted:f.has('adopted'),exception:f.has('exception'),documents:f.has('documents'),documentNotes:f.get('documentNotes'),notes:f.get('notes')};if(candidate.people.some(x=>x.id===p.id))candidate.people=candidate.people.map(x=>x.id===p.id?updated:x);else candidate.people.push(updated);await commitCandidate(candidate);if(!selected)selected=p.id;render();},{deleteFn:id?async()=>{if(current.assets.some(a=>a.owners[id])||current.people.some(p=>p.parents.includes(id))||current.relations.some(r=>r.a===id||r.b===id)||current.households.some(h=>h.a===id||h.b===id))throw Error('Osoba má vazby nebo majetek. Nejprve je upravte.');current.people=current.people.filter(p=>p.id!==id);if(selected===id)selected='';await save();}:undefined});}
function editRelation(id){const r=current.relations.find(x=>x.id===id)||{id:uid(),type:'marriage',start:'',end:''};modal('Partnerský vztah',`<div class="form-grid"><label>Osoba A<select name="a" required>${peopleOptions(r.a)}</select></label><label>Osoba B<select name="b" required>${peopleOptions(r.b)}</select></label><label>Právní forma<select name="type">${opts([['marriage','Manželství'],['partner','Nesezdané soužití'],['registered','Registrované partnerství — posoudit'],['partnership','Partnerství — posoudit']],r.type)}</select></label>${input('start','Vznik vztahu',r.start,'date','required')}${input('end','Zánik / rozvod (prázdné = trvá)',r.end,'date')}</div>`,async f=>{const c=clone(current);c.relations=c.relations.filter(x=>x.id!==r.id);c.relations.push({...r,...Object.fromEntries(f)});await commitCandidate(c);},{deleteFn:id?async()=>{current.relations=current.relations.filter(x=>x.id!==id);await save();}:undefined});}
function addChildren(){modal('Rychlé přidání dětí',`<label>Společný právní rodič<select name="parent" required>${peopleOptions(selected)}</select></label><p>Každý řádek: jméno; datum narození ve formátu RRRR-MM-DD. Dalšího rodiče lze doplnit v detailu.</p><label>Děti<textarea name="children" required placeholder="Anna Nováková; 2014-09-04&#10;Tomáš Novák; 2005-02-18"></textarea></label>`,async f=>{const c=clone(current);for(const line of f.get('children').trim().split('\n')){const [name,birth]=line.split(';').map(s=>s.trim());if(!name||!birth)throw Error('Každý řádek musí obsahovat jméno; datum narození.');c.people.push({id:uid(),name,birth,parents:[f.get('parent')]});}await commitCandidate(c);});}
function addHousehold(){modal('Společná domácnost',`<div class="form-grid"><label>Osoba A (poskytuje výživu)<select name="a" required>${peopleOptions(selected)}</select></label><label>Osoba B<select name="b" required>${peopleOptions()}</select></label>${input('since','Společná domácnost od','','date','required')}</div><div class="checks">${check('care','Péče o společnou domácnost.',false)}${check('dependent','Osoba B je výživově závislá na osobě A.',false)}${check('verified','Podmínky jsou ověřené pro tento model.',false)}</div><p>Pro nárok je třeba nejméně rok společné domácnosti před smrtí a alespoň jedna z uvedených podmínek. Výživová závislost platí směrově: osoba B může dědit po osobě A, nikoli automaticky obráceně.</p>`,async f=>{const c=clone(current);c.households.push({id:uid(),a:f.get('a'),b:f.get('b'),since:f.get('since'),care:f.has('care'),dependent:f.has('dependent'),verified:f.has('verified')});await commitCandidate(c);});}
function editAsset(id,kind='asset'){const a=current.assets.find(x=>x.id===id)||{id:uid(),name:'',kind,value:0,currency:'CZK',regime:'exclusive',category:kind==='debt'?'Hypotéky':'Nemovitosti',owners:{},verified:false,liquid:false};modal(a.kind==='debt'?'Závazek':'Majetková položka',`<div class="form-grid">${input('name','Název',a.name,'text','required')}<label>Kategorie<select name="category">${opts(a.kind==='debt'?debtCategories:assetCategories,a.category)}</select></label>${input('value','Odhadovaná hodnota celé položky',a.intakeUnknownValue?'':a.value,'number','min="0" step="0.01" required')}<label>Měna<select name="currency">${opts(['CZK','EUR','USD'],a.currency)}</select></label><label>Právní režim<select name="regime">${opts(['exclusive','shares','sjm','modified','unknown'].map(x=>[x,regimeName(x)]),a.regime)}</select></label>${input('acquired','Datum nabytí',a.acquired,'date')}<label>Způsob nabytí<select name="acquisition">${opts(['Koupě','Před manželstvím','Dar','Dědictví','Převod mezi manžely','Jiné'],a.acquisition)}</select></label><label>Související dluh<select name="relatedDebt">${opts([['','— bez vazby —'],...current.assets.filter(x=>x.kind==='debt'&&x.id!==a.id).map(x=>[x.id,x.name])],a.relatedDebt)}</select></label></div><h3 style="margin-top:20px">Vlastníci / modelové podíly (%)</h3><p>Součet 100 %. U modelu standardního SJM vyplňte 50 % u obou manželů.</p><div class="owner-grid">${current.people.map(p=>input('owner_'+p.id,esc(p.name),(a.owners[p.id]||0)*100,'number','min="0" max="100" step="any"')).join('')}</div><div class="checks">${check('verified','Použít uvedené vlastnictví a částku pro tento model.',a.verified||!!current.intake?.reviewed)}${check('liquid','Majetek lze považovat za likvidní.',a.liquid)}</div><label>Zatížení, smluvený režim, vnosy a poznámky<textarea name="notes">${esc(a.notes)}</textarea></label>`,async f=>{const c=clone(current),owners={};for(const p of c.people){const n=Number(f.get('owner_'+p.id))/100;if(n)owners[p.id]=n;}const updated={...a,intakeUnknownValue:false,name:f.get('name').trim(),category:f.get('category'),value:Number(f.get('value')),currency:f.get('currency'),regime:f.get('regime'),owners,verified:f.has('verified'),liquid:f.has('liquid'),acquired:f.get('acquired'),acquisition:f.get('acquisition'),relatedDebt:f.get('relatedDebt'),notes:f.get('notes'),updated:today()};c.assets=c.assets.filter(x=>x.id!==a.id);c.assets.push(updated);if(updated.acquisition==='Převod mezi manžely')c.gifts=true;await commitCandidate(c);},{deleteFn:id?async()=>{current.assets=current.assets.filter(x=>x.id!==id);await save();}:undefined});}
function transfer(){modal('Varianta převodu za života',`<div class="form-grid"><label>Položka<select name="asset" required>${opts(current.assets.filter(a=>a.kind==='asset').map(a=>[a.id,a.name]))}</select></label><label>Dárce<select name="from" required>${peopleOptions(selected)}</select></label><label>Nabyvatel<select name="to" required>${peopleOptions()}</select></label>${input('share','Převáděný podíl z celé položky (%)',100,'number','min="0.01" max="100" step="any" required')}</div><div class="notice">Převod ze SJM vyžaduje samostatné právní posouzení. Zde lze modelovat výlučný nebo podílový majetek.</div>`,async f=>{const c=clone(current),a=c.assets.find(a=>a.id===f.get('asset')),from=f.get('from'),to=f.get('to'),part=Number(f.get('share'))/100;if(!a||from===to||part<=0||part>(a.owners[from]||0)+1e-9||a.regime==='sjm')throw Error('Neplatný podíl, shodné osoby nebo převod ze SJM.');a.owners[from]-=part;if(a.owners[from]<1e-9)delete a.owners[from];a.owners[to]=(a.owners[to]||0)+part;a.regime=Object.keys(a.owners).length===1?'exclusive':'shares';a.acquisition='Dar';a.notes=(a.notes||'')+' Model převodu za života.';c.id=uid();c.name+=' — převod';c.gifts=true;c.demo=false;c.updated=new Date().toISOString();const errors=validate(c);if(errors.length)throw Error(errors.join(' '));await repo.put(c);cases=await repo.all();openCase(c.id);page='assets';render();});}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function importFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);input.oncancel=()=>input.remove();input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>5_000_000)throw Error('Maximum 5 MB.');const text=await file.text(),raw=JSON.parse(text);let c;
 if(raw.type===intakeType){const {data,candidate}=readExchangeFile(text);c=candidate;const p=exchangePreview(data,cases);
 const totals=Object.entries(p.currencies).map(([currency,v])=>`<li>${esc(currency)}: aktiva ${esc(v.assets.toLocaleString('cs-CZ'))}, dluhy ${esc(v.debts.toLocaleString('cs-CZ'))}; neznámé částky ${v.unknown}</li>`).join('');
 const rows=data.assets.map(a=>`<tr><td>${esc(a.name)}</td><td>${a.valueUnknown||a.value===''?'Nevím':esc(a.value+' '+a.currency)}</td><td>${esc(({me:'Klient',person:'Uvedená osoba',joint:'Společné jmění',shares:'Podíly',unknown:'Nevím'})[a.owner]||'Nevím')}</td></tr>`).join('');
 modal('Náhled přenosu údajů',`<h3>${esc(p.name)}</h3><p>${p.status==='draft'?'Rozpracované pracovní podklady — nejsou potvrzením klienta.':'Dokončený dotazník klienta.'} Zdroj: ${p.source==='filip-crm'?'CRM':p.source==='family-plan'?'Rodinný plán / dotazník':'Dotazník'}.</p><p>${p.people} osob · ${p.assets} položek · ${p.unknownOwners} neznámých vlastnictví · ${p.contracts} smluv</p><ul>${totals}</ul><p>Částky jsou součty celých uvedených položek po měnách. Nejsou čistým majetkem klienta. Pojistné krytí se do nich nezapočítává.</p><div class="table-wrap"><table><thead><tr><th>Položka</th><th>Částka</th><th>Vlastnictví</th></tr></thead><tbody>${rows}</tbody></table></div>${p.duplicates.length?`<div class="notice">Tento klient už má případ: ${p.duplicates.map(c=>esc(c.name)).join(', ')}. Původní případ zůstane zachovaný.</div><label><input type="checkbox" name="newCopy" required> Chci vytvořit samostatný nový případ pro kontrolu a porovnání.</label>`:'<p>Vytvoří se nový případ. Žádný existující případ nebude přepsán.</p>'}`,async f=>{if(p.duplicates.length&&!f.has('newCopy'))throw Error('Potvrďte vytvoření samostatné kopie.');await saveImported(c);},{submitLabel:'Vytvořit nový případ'});
 }else{c=parseCase(text);await saveImported(c);}
 }catch(e){toast('Import se nezdařil: '+e.message);}finally{input.remove();}};input.click();}
async function saveImported(c){c.id=uid();c.updated=new Date().toISOString();await repo.put(c);cases=await repo.all();openCase(c.id);if(c.intake){page='intake';render();}toast('Vytvořen nový případ. Původní případy zůstaly zachované.');}
async function exchangeFile(){const d=exportExchange(current);current.exchange=clone(d.exchange);current.exchangeClientId=current.exchangeClientId||(current.intake?'self':planPeople(current)[0]?.id);await repo.put(current);cases=await repo.all();return d;}

async function newCase(){modal('Nový klientský případ',input('name','Název případu','','text','required maxlength="150"'),async f=>{const c=blank(f.get('name').trim());await repo.put(c);cases=await repo.all();openCase(c.id);page='family';render();});}
async function action(a){switch(a){case 'toggle-tree':showAll=!showAll;render();break;case 'simulate-person':page='simulation';scenario='A';reset();render();break;case 'new':return newCase();case 'demo':{const c=demo();await repo.put(c);cases=await repo.all();openCase(c.id);break;}case 'person':return editPerson();case 'children':return addChildren();case 'relation':return editRelation();case 'household':return addHousehold();case 'transfer':return transfer();case 'import':return importFile();case 'exchange-export':{const d=await exchangeFile();if(embedded){sendCrmTransfer(d);break;}download('prenos-do-crm-'+today()+'.json',JSON.stringify(d,null,2),'application/json');toast('Soubor pro CRM byl připraven. Zůstává rozpracovaný, bez klientských potvrzení.');break;}case 'prefill-questionnaire':{const r=await fetch('./dotaznik-samostatny.html');if(!r.ok)throw Error('Samostatný dotazník není dostupný.');const d=await exchangeFile();download('dotaznik-pro-klienta.html',prefilledQuestionnaire(await r.text(),d),'text/html');toast('Dotazník přiložte k e-mailu. Klient vrátí stažený soubor odpovědí JSON.');break;}case 'export':download('rodinny-plan-'+today()+'.json',JSON.stringify(current,null,2),'application/json');toast('Záloha byla připravena ke stažení.');break;case 'duplicate':{const c=clone(current);c.id=uid();c.name+=' — kopie';c.updated=new Date().toISOString();await repo.put(c);cases=await repo.all();openCase(c.id);break;}case 'reset':reset();render();break;case 'apply-death':{if(!lastResult||lastResult.errors.length)break;history.push({name:personName(selected),date:active().date});model=applyDeath(active(),lastResult);selected=model.people.find(p=>!p.dead&&!p.death&&p.id!=='STATE')?.id||'';render();break;}case 'questionnaire-link':{const url=new URL('./dotaznik.html',location.href).href;try{await navigator.clipboard.writeText(url);toast('Odkaz zkopírován.');}catch{modal('Odkaz pro klienta',input('url','Zkopírujte odkaz',url),async()=>{});}break;}case 'questionnaire-html':{const r=await fetch('./dotaznik-samostatny.html');if(!r.ok){toast('Samostatný dotazník není dostupný. Použijte odkaz.');break;}download('dotaznik-rodinny-plan.html',await r.text(),'text/html');break;}case 'print':$('#presentation-frame')?.contentWindow.print();break;case 'html':download('fair-life-'+reportType+'.html',await getPresentation(),'text/html');break;case 'both-html':for(const kind of ['inheritance','crisis'])download('fair-life-'+kind+'.html',await getPresentation(kind),'text/html');toast('Oba plány jsou připravené ke stažení. Pokud prohlížeč povolí jen jeden, stáhněte druhý samostatně.');break;}}

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.closest('dialog'))return;try{if(b.dataset.reportType){reportType=b.dataset.reportType;page='report';render();return;}if(b.dataset.crisisAdd){editCrisis(b.dataset.crisisAdd);return;}if(b.dataset.crisisKey){editCrisis(b.dataset.crisisKey,Number(b.dataset.crisisIndex));return;}if(b.hasAttribute('data-accept-intake')){acceptClientAnswers(current);await save();page='overview';render();return;}if(b.dataset.page){if(b.closest('#intake-review')){const f=new FormData($('#intake-review'));current.intake.issues.forEach((i,n)=>{i.note=String(f.get('note_'+n)||'').trim();i.resolved=f.has('done_'+n);});if(!readyToReview(current))current.intake.reviewed=false;await repo.put(current);cases=await repo.all();}page=b.dataset.page;render();return;}if(b.dataset.open){openCase(b.dataset.open);return;}if(b.dataset.person){selected=b.dataset.person;beneficiary=defaultPartner(active(),selected);render();return;}if(b.dataset.scenario){scenario=b.dataset.scenario;if(scenario!=='G')reset();render();return;}if(b.dataset.jumpField){document.getElementById(b.dataset.jumpField)?.focus();return;}if(b.dataset.editPerson!==undefined){editPerson(b.dataset.editPerson);if(b.dataset.focusField)requestAnimationFrame(()=>document.querySelector('#dialog-form [name="'+b.dataset.focusField+'"]')?.focus());return;}if(b.dataset.editRelation){editRelation(b.dataset.editRelation);return;}if(b.dataset.addAsset){editAsset(null,b.dataset.addAsset);return;}if(b.dataset.editAsset){editAsset(b.dataset.editAsset);if(b.dataset.focusField)requestAnimationFrame(()=>document.querySelector('#dialog-form [name="'+b.dataset.focusField+'"]')?.focus());return;}if(b.dataset.deleteHousehold){current.households=current.households.filter(x=>x.id!==b.dataset.deleteHousehold);await save();return;}if(b.dataset.deleteCase){const id=b.dataset.deleteCase;modal('Smazat lokální případ?',`<p>Smaže se případ <b>${esc(cases.find(c=>c.id===id).name)}</b> z tohoto prohlížeče. Bez JSON zálohy jej nebude možné obnovit.</p>`,async()=>{await repo.remove(id);if(current?.id===id)current=null;cases=await repo.all();page='cases';render();});return;}if(b.dataset.action)await action(b.dataset.action);}catch(error){toast(error.message);}});
document.addEventListener('change',e=>{try{if(e.target.id==='sim-person'){selected=e.target.value;beneficiary=defaultPartner(active(),selected);render();}if(e.target.id==='beneficiary'){beneficiary=e.target.value;render();}if(e.target.id==='sim-date'){if(!e.target.value||history.length&&e.target.value<history.at(-1).date)throw Error('Datum nesmí předcházet předchozí události.');model??=clone(current);model.date=e.target.value;render();}}catch(error){toast(error.message);render();}});
document.addEventListener('submit',async e=>{if(e.target.id==='dialog-form')return;const id=e.target.id;if(!['settings-form','manual-form','financial-form','plan-form'].includes(id))return;e.preventDefault();try{const f=new FormData(e.target),c=clone(current);if(id==='plan-form'){if(f.get('primary')===f.get('partner'))throw Error('Pro druhý scénář vyberte jinou osobu.');c.plan={...(c.plan||{}),primary:f.get('primary'),partner:f.get('partner'),reviewDate:f.get('reviewDate')};c.advisor={...advisorOf(c)};for(const k of ['name','phone','email','web','address'])c.advisor[k]=String(f.get(k)||'').trim();if(!c.advisor.name)throw Error('Vyplňte jméno zpracovatele.');}if(id==='settings-form'){c.name=f.get('name').trim();c.date=f.get('date');for(const key of ['complete','sjmConfirmed','international','gifts'])c[key]=f.has(key);}if(id==='manual-form')for(const key of Object.keys(manualFields))c.manual[key]=f.get(key);if(id==='financial-form'){c.financialProvided=true;for(const key of Object.keys(financialFields))c.financial[key]=Number(f.get(key));if(c.intake)c.intake.unknownFinancial=[];}await commitCandidate(c);toast('Změny byly uloženy.');}catch(error){toast(error.message);}});
try{cases=await repo.all();if(embedded){openCase(cases[0].id);const saved=initialUi();page=saved?.page&&pages[saved.page]&&saved.page!=='cases'?saved.page:'assets';selected=saved?.selected||selected;scenario=saved?.scenario||'A';beneficiary=saved?.beneficiary||beneficiary;model=saved?.model||null;history=saved?.history||[];reportType=saved?.reportType||'inheritance';await repo.put(current);saveStatus='Uloženo u klienta v CRM';}render();}catch(e){saveStatus='Úložiště nedostupné';render();toast(e.message);}

window.CrmFamilyFrame={dirty:false,save:()=>{if(window.CrmFamilyFrame.dirty)throw Error('Nejdříve uložte rozepsaný formulář jeho tlačítkem Uložit.');return repo.put(current);},replace(value){current=value;cases=[value];reset();render();}};
if(embedded){document.getElementById('dialog').addEventListener('close',()=>{if(!saveStatus.startsWith('Neuloženo'))window.CrmFamilyFrame.dirty=false;});document.addEventListener('input',e=>{if(e.target.closest('form'))window.CrmFamilyFrame.dirty=true;});document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b&&window.CrmFamilyFrame.dirty&&!confirm('Formulář není uložený. Opustit jej bez uložení?')){e.preventDefault();e.stopImmediatePropagation();}},true);window.addEventListener('beforeunload',e=>{if(window.CrmFamilyFrame.dirty){e.preventDefault();e.returnValue='';}});}
